

# This file was *autogenerated* from the file /Users/masaori/git/masaori/math/.claude/worktrees/polished-sleeping-badger/exact-solution-of-2d-ising-model/sagemath/check/103_cos_arctan_sin_arctan/check_02_arctan_definition_via_arcsin.sage
from sage.all_cmdline import *   # import sage library

_sage_const_300 = Integer(300); _sage_const_250 = Integer(250); _sage_const_0 = Integer(0); _sage_const_1 = Integer(1); _sage_const_2 = Integer(2); _sage_const_10 = Integer(10); _sage_const_6 = Integer(6); _sage_const_3 = Integer(3); _sage_const_4 = Integer(4); _sage_const_100 = Integer(100); _sage_const_5 = Integer(5); _sage_const_9 = Integer(9)# ---------------------------------------------------------
# <cos_arctan_sin_arctan> の前提となる定義の整合性
#   本文（<calc_formulae_014_definition_inverse_trig_functions>）は
#     arctan(x) := arcsin( x / sqrt(1+x^2)^{(R_{>=0})} )
#     cos(theta) := sqrt(1 - (sin theta)^2)^{(R_{>=0})}   (|theta| <= pi/2)
#   と定めている。check_01 では Sage の arctan / cos / sin を本文の定義の実装として
#   使っているので、その一致をここで確認する（一致しないと check_01 の左辺が
#   本文の左辺でなくなる）。
#
# さらに本文の証明の途中式
#   cos(arcsin(t)) = sqrt(1 - t^2),  sin(arcsin(t)) = t
# を独立に確認する。
# ---------------------------------------------------------
import os
_dir = os.path.dirname(os.path.abspath(__file__)) if '__file__' in dir() else '.'
load(os.path.join(_dir, '../../_shared/operators.sage'))

RF = RealField(_sage_const_300 )
ITERS = _sage_const_250 

def sqrt_nonneg_bisect(a):
    a = RF(a)
    lo, hi = RF(_sage_const_0 ), RF(_sage_const_1 ) + a
    for _ in range(ITERS):
        mid = (lo + hi) / _sage_const_2 
        if mid * mid <= a:
            lo = mid
        else:
            hi = mid
    return (lo + hi) / _sage_const_2 

XS = [RF(v) for v in [
    _sage_const_0 , _sage_const_1 /_sage_const_10 **_sage_const_6 , -_sage_const_1 /_sage_const_10 **_sage_const_6 , _sage_const_1 /_sage_const_3 , -_sage_const_1 /_sage_const_3 , _sage_const_1 /_sage_const_2 , -_sage_const_1 /_sage_const_2 , _sage_const_1 , -_sage_const_1 , _sage_const_2 , -_sage_const_2 ,
    _sage_const_4 /_sage_const_3 , -_sage_const_4 /_sage_const_3 , _sage_const_10 , -_sage_const_10 , _sage_const_100 , -_sage_const_100 , _sage_const_10 **_sage_const_6 , -_sage_const_10 **_sage_const_6 ,
]]
TS = [RF(v) for v in [
    _sage_const_0 , _sage_const_1 /_sage_const_10 **_sage_const_6 , -_sage_const_1 /_sage_const_10 **_sage_const_6 , _sage_const_1 /_sage_const_4 , -_sage_const_1 /_sage_const_4 , _sage_const_1 /_sage_const_2 , -_sage_const_1 /_sage_const_2 , _sage_const_3 /_sage_const_5 , -_sage_const_3 /_sage_const_5 ,
    _sage_const_9 /_sage_const_10 , -_sage_const_9 /_sage_const_10 , _sage_const_1 , -_sage_const_1 ,
]]

rep = CheckReport("<cos_arctan_sin_arctan> の土台: arctan の定義と arcsin の性質")

for x in XS:
    t = x / sqrt_nonneg_bisect(_sage_const_1  + x**_sage_const_2 )
    rep.truth(-_sage_const_1  <= t <= _sage_const_1 , "x/sqrt(1+x^2) in [-1,1] @x=%s" % x)
    rep.close(float(RF(x).arctan()), float(RF(t).arcsin()),
              "arctan(x) = arcsin(x/sqrt(1+x^2)) @x=%s" % x)

for t in TS:
    a = RF(t).arcsin()
    rep.truth(-RF(pi) / _sage_const_2  <= a <= RF(pi) / _sage_const_2 , "arcsin(t) in [-pi/2,pi/2] @t=%s" % t)
    rep.close(float(a.sin()), float(t), "sin(arcsin t) = t @t=%s" % t)
    # cos(theta) := sqrt(1 - sin^2 theta)（本文の定義）と Sage の cos の一致
    rep.close(float(a.cos()), float(sqrt_nonneg_bisect(_sage_const_1  - t**_sage_const_2 )),
              "cos(arcsin t) = sqrt(1-t^2) @t=%s" % t)
    # arcsin の奇関数性（本文の定義は y'<0 側を -arcsin(-y') で定めている）
    rep.close(float(RF(-t).arcsin()), float(-a), "arcsin(-t) = -arcsin(t) @t=%s" % t)

rep.finish()

